<script module lang="ts">
/**
 * A round mark identifying a person or workspace (`design/components/avatar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, avatarTone, initialsOf, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/avatar.module.css'

export type AvatarSize = NonNullable<AvatarProps['size']>

export interface AvatarProps {
  /**
   * Set only when the avatar stands alone; beside a visible name it would repeat the name, so it
   * is `aria-hidden` instead.
   */
  label?: string
  /**
   * Initials come from this. "Ada Lovelace" → AL; one word → its first two.
   */
  name: string
  size?: 'sm' | 'md' | 'lg'
  src?: string
}
</script>

<script lang="ts">
let { label: labelOwn, name, size = 'md', src }: AvatarProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, name: name, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let failed = $state('')
const initials = $derived(initialsOf(name))
const showImage = $derived(src !== undefined && failed !== src)
const fallback = $derived(initials === '' ? 'icon' : 'initials')
const named = $derived(label !== undefined)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    class={styles.avatar}
    data-size={size}
    data-fallback={showImage ? undefined : fallback}
    data-tone={fallback === 'initials' && !showImage ? avatarTone(name) : undefined}
    role={(named) ? 'img' : undefined}
    aria-label={label}
    aria-hidden={(!named) ? true : undefined}
    data-member="avatar"
    >{#if showImage
      }<img
        class={styles.image}
        {src}
        alt=""
        draggable="false"
        onerror={() => { failed = src ?? '' }}
    />{/if
    }{#if fallback === 'icon'
      }<Icon name="user" {size}
    />{:else
      }<span class={styles.initials}>{initials}</span
    >{/if
  }</span
>{/if
}{@render joined.end?.()}
